'use strict';

/* ─── CONFIG API ─── */
var API_BASE = 'https://portal-apps-api.onrender.com';

/* ─── LOGO ─── */
var LOGO = 'data:image/png;base64,';
document.getElementById('s-logo').src = LOGO;
document.getElementById('h-logo').src = LOGO;
var _fi = document.createElement('link');
_fi.rel = 'icon'; _fi.href = LOGO;
document.head.appendChild(_fi);

/* ─── ESTADO ─── */
var apps = [];
var currentCat  = 'all';
var currentSort = 'recent';
var searchQ     = '';
var editingId   = null;
var splashDone  = false;

/* ─── UTILS ─── */
function qs(s) { return document.querySelector(s); }
function xe(s) {
  return String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function nx(s) { return (s == null ? '' : s).toLowerCase(); }

/* ─── API ─── */
function apiFetch(path, opts) {
  return fetch(API_BASE + path, Object.assign(
    { headers: { 'Content-Type': 'application/json' } }, opts || {}
  )).then(function(r) {
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.json();
  });
}

function loadApps() {
  showLoading(true);
  return apiFetch('/api/apps')
    .then(function(data) { apps = data || []; })
    .catch(function() { apps = []; showToast('Sin conexión al servidor', true); })
    .finally(function() { showLoading(false); render(); });
}

function loadConfig() {
  return apiFetch('/api/config')
    .then(function(cfg) {
      if (cfg.bg_url && cfg.bg_url.trim()) {
        document.body.style.backgroundImage   = 'url(' + cfg.bg_url + ')';
        document.body.style.backgroundSize    = (cfg.bg_size || 40) + '%';
        document.body.style.backgroundRepeat  = 'no-repeat';
        document.body.style.backgroundPosition = 'center';
        qs('#bg-size').value = cfg.bg_size || 40;
      }
      if (cfg.bg_dark) {
        qs('#bg-dark').value = cfg.bg_dark;
        applyBgDark(parseInt(cfg.bg_dark));
      }
    }).catch(function() {});
}

function saveConfig(key, value) {
  apiFetch('/api/config', {
    method: 'PUT',
    body: JSON.stringify({ key: key, value: String(value) })
  }).catch(function() {});
}

/* ─── SPLASH ─── */
var CIRC = 2 * Math.PI * 190;
var _rfg = qs('#ring-fg');
_rfg.style.strokeDasharray  = CIRC;
_rfg.style.strokeDashoffset = CIRC;
function setRing(p) { _rfg.style.strokeDashoffset = CIRC * (1 - p / 100); }

var _twIdx = 0, _twText = 'Portal de Aplicaciones';
function typeWriter() {
  var el = qs('#typewriter'); if (!el) return;
  el.textContent = _twText.slice(0, _twIdx) + (_twIdx < _twText.length ? '|' : '');
  if (_twIdx <= _twText.length) { _twIdx++; setTimeout(typeWriter, 65); }
}
setTimeout(typeWriter, 1100);

function goApp() {
  if (splashDone) return; splashDone = true;
  qs('#splash').classList.add('fade-out');
  setTimeout(function() {
    qs('#splash').style.display = 'none';
    qs('#dashboard').classList.add('show');
    qs('#fab').classList.remove('hidden');
    loadConfig();
    loadApps();
  }, 750);
}
window.goApp = goApp;

/* ─── MATRIX CANVAS ─── */
(function() {
  var cv = qs('#matrix-canvas'), ctx = cv.getContext('2d');
  var W, H, CX, CY, cols, drops;
  var CHARS = '01アイウエオカ<>{}[]|/\\'.split('');

  function resize() {
    W = cv.width = window.innerWidth; H = cv.height = window.innerHeight;
    CX = W / 2; CY = H / 2;
    cols = Math.floor(W / 18); drops = [];
    for (var i = 0; i < cols; i++) drops[i] = Math.random() * -50;
  }
  resize(); window.addEventListener('resize', resize);

  function frame() {
    if (splashDone) return;
    ctx.fillStyle = 'rgba(5,10,15,.08)'; ctx.fillRect(0, 0, W, H);
    ctx.font = '13px monospace';
    for (var i = 0; i < cols; i++) {
      var x = i * 18, y = drops[i] * 18;
      var dist = Math.sqrt(Math.pow(x - CX, 2) + Math.pow(y - CY, 2));
      var alpha = dist < 160 ? (dist / 160) * 0.35 : 0.82;
      var bright = drops[i] > 0 && Math.random() > 0.97;
      ctx.fillStyle = bright ? 'rgba(255,255,255,' + alpha + ')' : 'rgba(251,191,36,' + alpha + ')';
      ctx.fillText(CHARS[Math.floor(Math.random() * CHARS.length)], x, y);
      if (y > H && Math.random() > 0.97) drops[i] = 0;
      drops[i] += 0.5;
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();

/* ─── RING TIMER ─── */
var _DUR = 2800, _t0 = performance.now();
(function tick(now) {
  var p = Math.min(100, Math.round((now - _t0) / _DUR * 100));
  setRing(p);
  var el = qs('#splash-pct'); if (el) el.textContent = p + '%';
  if (p < 100) requestAnimationFrame(tick);
})(_t0);
setTimeout(goApp, _DUR);

/* ─── RENDER ─── */
function getCats() {
  var seen = {}, list = [];
  apps.forEach(function(a) { if (!seen[a.category]) { seen[a.category] = 1; list.push(a.category); } });
  return list;
}

function renderFilters() {
  var cats = getCats();
  qs('#cat-list').innerHTML = cats.map(function(c) {
    return '<option value="' + xe(c) + '"></option>';
  }).join('');
  var allItems = [{ k: 'all', l: 'Todos', n: apps.length }].concat(cats.map(function(c) {
    return { k: c, l: c, n: apps.filter(function(a) { return a.category === c; }).length };
  }));
  qs('#cat-pills').innerHTML = allItems.map(function(item) {
    return '<button class="pill' + (item.k === currentCat ? ' active' : '') +
      '" data-cat="' + xe(item.k) + '">' +
      '<span class="pill-dot"></span>' + xe(item.l) +
      '<span style="margin-left:.2rem;font-size:.58rem;opacity:.7">(' + item.n + ')</span>' +
      '</button>';
  }).join('');
}

function filteredApps() {
  var q = nx(searchQ.trim());
  var list = apps.filter(function(a) {
    var inCat = currentCat === 'all' || a.category === currentCat;
    var inQ   = !q || nx(a.name).indexOf(q) >= 0 || nx(a.category).indexOf(q) >= 0 || nx(a.description || '').indexOf(q) >= 0;
    return inCat && inQ;
  });
  if (currentSort === 'name') list.sort(function(a, b) { return a.name.localeCompare(b.name, 'es'); });
  else if (currentSort === 'category') list.sort(function(a, b) { return a.category.localeCompare(b.category, 'es'); });
  else list.sort(function(a, b) { return new Date(b.created_at || 0) - new Date(a.created_at || 0); });
  list.sort(function(a, b) { return (b.favorite ? 1 : 0) - (a.favorite ? 1 : 0); });
  return list;
}

function renderGrid() {
  var grid = qs('#grid'), empty = qs('#empty-state');
  var list = filteredApps();
  qs('#app-counter').textContent = list.length + ' / ' + apps.length + ' app' + (apps.length !== 1 ? 's' : '');
  if (!list.length) { grid.innerHTML = ''; empty.classList.remove('hidden'); return; }
  empty.classList.add('hidden');
  grid.innerHTML = list.map(function(a, i) {
    var url = /^https?:\/\//i.test(a.url) ? a.url : 'https://' + a.url;
    return '<div class="app-card" data-id="' + xe(a.id) + '" style="animation:appIn .2s ease ' + Math.min(i*30,300) + 'ms both">' +
      '<button class="card-fav' + (a.favorite ? ' active' : '') + '" data-act="fav">&#9733;</button>' +
      '<div class="card-category">' + xe(a.category) + '</div>' +
      '<div class="card-name">' + xe(a.name) + '</div>' +
      '<div class="card-footer">' +
        '<a class="card-open-btn" href="' + xe(url) + '" target="_blank" rel="noopener">Abrir &#8599;</a>' +
        '<div class="card-actions">' +
          '<button class="card-act" data-act="edit">&#9998;</button>' +
          '<button class="card-act del" data-act="del">&#10005;</button>' +
        '</div>' +
      '</div>' +
    '</div>';
  }).join('');
}

function render() { renderFilters(); renderGrid(); }

/* ─── GRID EVENTOS ─── */
qs('#grid').addEventListener('click', function(e) {
  var btn = e.target.closest('[data-act]'); if (!btn) return;
  e.stopPropagation();
  var card = btn.closest('.app-card'); if (!card) return;
  var id = card.getAttribute('data-id');
  var act = btn.getAttribute('data-act');
  if (act === 'edit') { openModal(id); }
  else if (act === 'del') {
    var app = apps.find(function(x) { return x.id === id; });
    if (app && confirm('Eliminar "' + app.name + '"?')) {
      apiFetch('/api/apps/' + id, { method: 'DELETE' })
        .then(function() { apps = apps.filter(function(x) { return x.id !== id; }); render(); showToast('Eliminada'); })
        .catch(function() { showToast('Error al eliminar', true); });
    }
  } else if (act === 'fav') {
    var app2 = apps.find(function(x) { return x.id === id; });
    if (app2) {
      apiFetch('/api/apps/' + id, { method: 'PUT', body: JSON.stringify({ favorite: !app2.favorite }) })
        .then(function(u) { app2.favorite = u.favorite; render(); })
        .catch(function() {});
    }
  }
});

/* ─── BUSCAR / FILTROS ─── */
qs('#search').addEventListener('input', function(e) { searchQ = e.target.value; renderGrid(); });
document.addEventListener('keydown', function(e) {
  if (e.key === '/' && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName) && qs('#modal-overlay').classList.contains('hidden')) {
    e.preventDefault(); qs('#search').focus();
  }
  if (e.key === 'Escape' && !qs('#modal-overlay').classList.contains('hidden')) closeModal();
});
qs('#cat-pills').addEventListener('click', function(e) {
  var b = e.target.closest('[data-cat]'); if (!b) return;
  currentCat = b.getAttribute('data-cat'); render();
});
qs('#sort-select').addEventListener('change', function(e) { currentSort = e.target.value; renderGrid(); });

/* ─── MODAL ─── */
var ICONS = ['\ud83d\udda5\ufe0f','\ud83d\udcca','\ud83d\udd27','\ud83e\uddba','\ud83d\udce6','\ud83d\udcc1','\ud83d\udcc8','\ud83d\udee1\ufe0f','\ud83d\udccb','\ud83e\udea6','\ud83d\udce7','\u2699\ufe0f','\ud83d\udea6','\ud83c\udfed','\ud83e\uddf0','\ud83d\udcdd','\ud83d\udd12','\ud83d\udca1','\ud83e\uddfe','\ud83d\udccc'];

function openModal(id) {
  editingId = id || null;
  var app = id ? apps.find(function(x) { return x.id === id; }) : null;
  qs('#modal-title').textContent = app ? 'EDITAR APLICACION' : 'AGREGAR APLICACION';
  qs('#f-icon').value  = app ? (app.icon || '\ud83d\udda5\ufe0f') : '\ud83d\udda5\ufe0f';
  qs('#f-name').value  = app ? (app.name || '') : '';
  qs('#f-url').value   = app ? (app.url  || '') : '';
  qs('#f-cat').value   = app ? (app.category || '') : '';
  qs('#f-desc').value  = app ? (app.description || '') : '';
  buildPicker(); hideErr();
  qs('#modal-overlay').classList.remove('hidden');
  setTimeout(function() { qs('#f-name').focus(); }, 60);
}
window.openModal = openModal;

function closeModal() {
  qs('#modal-overlay').classList.add('hidden');
  qs('#app-form').reset();
  qs('#f-icon').value = '\ud83d\udda5\ufe0f';
  hideErr(); editingId = null;
}
window.closeModal = closeModal;

function buildPicker() {
  qs('#icon-picker').innerHTML = ICONS.map(function(em) {
    return '<button type="button" class="icon-btn" data-em="' + em + '">' + em + '</button>';
  }).join('');
  qs('#icon-picker').querySelectorAll('[data-em]').forEach(function(b) {
    b.addEventListener('click', function() { qs('#f-icon').value = b.getAttribute('data-em'); });
  });
}

function showErr(m) { var el = qs('#form-error'); el.textContent = m; el.classList.remove('hidden'); }
function hideErr() { qs('#form-error').classList.add('hidden'); }

qs('#app-form').addEventListener('submit', function(e) {
  e.preventDefault(); hideErr();
  var icon = qs('#f-icon').value.trim() || '\ud83d\udda5\ufe0f';
  var name = qs('#f-name').value.trim();
  var url  = qs('#f-url').value.trim();
  var cat  = qs('#f-cat').value.trim();
  var desc = qs('#f-desc').value.trim();
  if (!name) { showErr('Nombre obligatorio.'); qs('#f-name').focus(); return; }
  if (!url)  { showErr('Enlace obligatorio.');  qs('#f-url').focus();  return; }
  if (!cat)  { showErr('Categoria obligatoria.'); qs('#f-cat').focus(); return; }
  if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
  try { new URL(url); } catch(er) { showErr('URL no valida.'); qs('#f-url').focus(); return; }

  var payload = { name: name, url: url, category: cat, description: desc, icon: icon };
  if (editingId) {
    apiFetch('/api/apps/' + editingId, { method: 'PUT', body: JSON.stringify(payload) })
      .then(function(u) {
        var idx = apps.findIndex(function(x) { return x.id === editingId; });
        if (idx >= 0) apps[idx] = u;
        closeModal(); render(); showToast('Actualizada');
      }).catch(function() { showErr('Error al guardar.'); });
  } else {
    apiFetch('/api/apps', { method: 'POST', body: JSON.stringify(payload) })
      .then(function(c) {
        apps.unshift(c); closeModal();
        currentCat = 'all'; searchQ = ''; qs('#search').value = '';
        render(); showToast('"' + name + '" agregada');
      }).catch(function() { showErr('Error al guardar.'); });
  }
});

/* ─── TOOLS MENU ─── */
var _tm = qs('#tools-menu');
qs('#tools-btn').addEventListener('click', function(e) { e.stopPropagation(); _tm.classList.toggle('hidden'); });
document.addEventListener('click', function(e) { if (!e.target.closest('#tools-wrap')) _tm.classList.add('hidden'); });

qs('#tools-menu').addEventListener('click', function(e) {
  var btn = e.target.closest('[data-action]'); if (!btn) return;
  _tm.classList.add('hidden');
  var act = btn.getAttribute('data-action');
  if (act === 'changeBg') { qs('#bg-file').click(); }
  else if (act === 'removeBg') { document.body.style.backgroundImage = ''; saveConfig('bg_url',''); showToast('Fondo eliminado'); }
  else if (act === 'exportApps') {
    var bl = new Blob([JSON.stringify(apps,null,2)],{type:'application/json'});
    var a = document.createElement('a'); a.href=URL.createObjectURL(bl); a.download='mis-apps.json';
    document.body.appendChild(a); a.click(); a.remove(); showToast('Exportado ('+apps.length+')');
  }
  else if (act === 'importApps') { qs('#import-file').click(); }
  else if (act === 'restoreApps') {
    if (confirm('Agregar app de ejemplo?')) {
      apiFetch('/api/apps',{method:'POST',body:JSON.stringify({name:'SGAS',url:'https://sgas-ssgg.github.io/sgas/#inicio',category:'SSOMA',description:'Sistema Gestion ATS',icon:'\ud83d\udee1\ufe0f'})})
        .then(function(c){apps.unshift(c);render();showToast('Ejemplo agregado');}).catch(function(){});
    }
  }
  else if (act === 'clearApps') {
    if (confirm('Eliminar TODAS las apps?')) {
      Promise.all(apps.map(function(a){return apiFetch('/api/apps/'+a.id,{method:'DELETE'});}))
        .then(function(){apps=[];render();showToast('Portal vaciado');}).catch(function(){});
    }
  }
});

/* ─── FONDO ─── */
qs('#bg-file').addEventListener('change', function(e) {
  var file = e.target.files[0]; if (!file) return;
  var reader = new FileReader();
  reader.onload = function(ev) {
    var d = ev.target.result;
    document.body.style.backgroundImage = 'url(' + d + ')';
    document.body.style.backgroundSize = qs('#bg-size').value + '%';
    document.body.style.backgroundRepeat = 'no-repeat';
    document.body.style.backgroundPosition = 'center';
    if (d.length < 1400000) { saveConfig('bg_url', d); showToast('Fondo actualizado'); }
    else { showToast('Fondo aplicado (imagen grande, no se sincroniza)'); }
  };
  reader.readAsDataURL(file); e.target.value = '';
});
qs('#bg-size').addEventListener('input', function() { document.body.style.backgroundSize = this.value + '%'; saveConfig('bg_size', this.value); });
qs('#bg-dark').addEventListener('input', function() { applyBgDark(parseInt(this.value)); saveConfig('bg_dark', this.value); });
function applyBgDark(v) {
  document.body.style.backgroundColor = 'rgb(' + Math.round(10+(v/100)*32) + ',' + Math.round(16+(v/100)*58) + ',' + Math.round(24+(v/100)*82) + ')';
}

/* ─── IMPORTAR ─── */
qs('#import-file').addEventListener('change', function(e) {
  var file = e.target.files[0]; if (!file) return;
  var r = new FileReader();
  r.onload = function(ev) {
    try {
      var data = JSON.parse(ev.target.result); if (!Array.isArray(data)) throw 0;
      if (!confirm('Importar ' + data.length + ' apps?')) { e.target.value=''; return; }
      Promise.all(data.map(function(item) {
        return apiFetch('/api/apps',{method:'POST',body:JSON.stringify({
          name: item.name||item.title||'Sin nombre', url: item.url||'#',
          category: item.category||item.cat||'General',
          description: item.description||item.desc||'', icon: item.icon||'\ud83d\udda5\ufe0f'
        })});
      })).then(function(c){apps=c.concat(apps);render();showToast('Importadas: '+c.length);})
        .catch(function(){showToast('Error al importar',true);});
    } catch(er) { showToast('JSON invalido',true); }
  };
  r.readAsText(file); e.target.value='';
});

/* ─── LOADING / TOAST ─── */
function showLoading(show) {
  qs('#loading').classList.toggle('hidden', !show);
  qs('#grid').style.display = show ? 'none' : '';
}
var _tt;
function showToast(msg, isErr) {
  var el = qs('#toast'); qs('#toast-msg').textContent = msg;
  el.classList.toggle('error', !!isErr);
  el.classList.add('show'); el.classList.remove('hidden');
  clearTimeout(_tt); _tt = setTimeout(function(){ el.classList.remove('show'); }, 2800);
}
